def format_price(cents, currency="USD"):
    symbol = "\u20ac" if currency == "EUR" else "$"
    return "%s%d.%02d" % (symbol, cents // 100, cents % 100)


def format_discount(cents, pct):
    off = cents * pct // 100
    return "-$%d.%02d" % (off // 100, off % 100)
